const VERSION='altrove-v8-zh-pitch15-20260919';const CORE=['./','./index.html','./style.css','./app.mjs','./domain.mjs','./data.json'];
self.addEventListener('install',event=>event.waitUntil(caches.open(VERSION).then(cache=>cache.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('altrove-')&&k!==VERSION).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==location.origin||url.pathname.endsWith('.mp3'))return;event.respondWith((async()=>{const cache=await caches.open(VERSION);const cached=await cache.match(req);if(cached)return cached;try{const response=await fetch(req);if(response.ok){try{await cache.put(req,response.clone())}catch{}}return response}catch{if(req.mode==='navigate')return await cache.match('./index.html')||Response.error();return Response.error()}})())});